INSERT INTO questions (id, lesson_id, position, prompt, explanation) VALUES
(101, 10, 1, $$CIA üçlüsündeki "I" harfi neyi ifade eder?$$, $$CIA: Confidentiality (gizlilik), Integrity (bütünlük), Availability (erişilebilirlik).$$),
(102, 10, 2, $$Kullanıcıyı sahte bir giriş sayfasına yönlendirip bilgilerini çalmayı amaçlayan saldırı hangisidir?$$, $$Phishing, güvenilir bir kurum gibi görünerek kullanıcıyı kandırmayı hedefler.$$),
(103, 10, 3, $$Kimlik doğrulama (authentication) neyi kontrol eder?$$, $$Authentication kim olduğunu, authorization ise neye erişebileceğini belirler.$$),
(104, 10, 4, $$Parolan çalınsa bile hesabını korumaya yardım eden yöntem hangisidir?$$, $$MFA, paroladan başka bir doğrulama faktörü (telefon, güvenlik anahtarı vb.) ister.$$),
(111, 11, 1, $$HTTPS varsayılan olarak hangi portu kullanır?$$, $$HTTPS 443, HTTP ise 80 numaralı portu kullanır.$$),
(112, 11, 2, $$Güvenlik duvarı için en güvenli varsayılan kural yaklaşımı hangisidir?$$, $$Default deny yaklaşımında yalnızca açıkça izin verilen trafik geçer.$$),
(113, 11, 3, $$HTTPS'in HTTP'ye göre temel avantajı nedir?$$, $$HTTPS iletişimi TLS ile şifreleyerek dinleme ve değiştirme saldırılarını önler.$$),
(114, 11, 4, $$Halka açık Wi-Fi'da trafiği şifreli bir tünelden geçiren araç hangisidir?$$, $$VPN, cihazınla VPN sunucusu arasında şifreli bir tünel kurar.$$),
(121, 12, 1, $$SQL enjeksiyonunu önlemenin en etkili yolu hangisidir?$$, $$Parametreli sorgularda girdi her zaman veri olarak işlenir, asla SQL kodu olarak çalıştırılmaz.$$),
(122, 12, 2, $$Sayfaya zararlı JavaScript enjekte edilmesine dayanan saldırı hangisidir?$$, $$Cross-Site Scripting (XSS), kullanıcının tarayıcısında saldırganın betiğini çalıştırır.$$),
(123, 12, 3, $$Kullanıcının, isteğindeki kimliği değiştirerek başkasının verisine erişebildiği açık hangisidir?$$, $$IDOR bir bozuk erişim kontrolü örneğidir; sunucu nesneye erişim yetkisini kontrol etmez.$$),
(124, 12, 4, $$OWASP Top 10 nedir?$$, $$OWASP Top 10, web güvenliğindeki en kritik riskleri düzenli olarak güncelleyen referans listedir.$$),
(131, 13, 1, $$Etik hackerlığı yasa dışı saldırıdan ayıran en temel unsur nedir?$$, $$Etik hackerlık her zaman sistem sahibinin yazılı izniyle ve belirlenmiş kapsam içinde yapılır.$$),
(132, 13, 2, $$Sızma testinin ilk aşaması genellikle hangisidir?$$, $$Test, hedef hakkında bilgi toplanan keşif (reconnaissance) aşamasıyla başlar.$$),
(133, 13, 3, $$Ağdaki açık portları ve servisleri taramak için yaygın kullanılan araç hangisidir?$$, $$Nmap; ağdaki cihazları, açık portları ve çalışan servisleri keşfetmek için kullanılan bir tarama aracıdır.$$),
(134, 13, 4, $$Sızma testi raporunda bulgular neye göre önceliklendirilir?$$, $$Bulgular etki ve olasılığa göre risk seviyesiyle önceliklendirilir; kritik açıklar önce kapatılır.$$);
