-- Constellation 3: Siber Güvenlik · "Kalkan"

                     difficulty, duration_min, xp_reward, star_x, star_y, sort_order) VALUES
(10, 'siber-guvenligin-temelleri', 3, $$Siber Güvenliğin Temelleri$$,
 $$Gizlilik, bütünlük ve erişilebilirlik üçlüsüyle güvenliğin temel kavramlarını ve yaygın tehditleri tanı.$$,
 ARRAY[$$CIA üçlüsünü (gizlilik, bütünlük, erişilebilirlik) açıklamak$$, $$Oltalama (phishing) saldırılarını tanımak$$,
       $$Güçlü parola ve çok faktörlü doğrulamanın önemini kavramak$$, $$Kimlik doğrulama ile yetkilendirmeyi ayırt etmek$$],
 ARRAY[$$Bilgi güvenliğinin üç temel hedefi CIA üçlüsü olarak bilinir: Gizlilik (Confidentiality) bilgiye yalnızca yetkililerin erişmesi, bütünlük (Integrity) bilginin izinsiz değiştirilmemesi, erişilebilirlik (Availability) ise sistemin ihtiyaç anında çalışır olmasıdır.$$,
       $$Saldırıların büyük kısmı teknolojiden çok insanı hedefler. Oltalama (phishing) e-postaları seni sahte bir sayfaya yönlendirip parolanı çalmaya çalışır. Gönderen adresini ve bağlantıyı tıklamadan önce kontrol etmek ilk savunma hattındır.$$,
       $$Kimlik doğrulama (authentication) senin kim olduğunu, yetkilendirme (authorization) ise neye erişebileceğini belirler. Güçlü ve benzersiz parolalar ile çok faktörlü doğrulama (MFA), çalınan bir parolanın tek başına yetmemesini sağlar.$$],
 'U_P23SqJaDc', 'BEGINNER', 30, 100, 130, 470, 1),
(11, 'ag-guvenligi', 3, $$Ağ Güvenliği ve Firewall$$,
 $$Portlar, protokoller ve güvenlik duvarlarıyla ağ trafiğini kontrol etmeyi; şifreli iletişimin önemini öğren.$$,
 ARRAY[$$Port ve protokol kavramlarını açıklamak$$, $$Güvenlik duvarının trafiği nasıl filtrelediğini anlamak$$,
       $$HTTP ile HTTPS arasındaki farkı kavramak$$, $$VPN'in hangi durumlarda koruma sağladığını bilmek$$],
 ARRAY[$$Ağdaki her hizmet bir port üzerinden konuşur: Web siteleri genellikle 443 (HTTPS), SSH bağlantıları 22 numaralı portu kullanır. Gereksiz açık bırakılan her port saldırgan için potansiyel bir kapıdır.$$,
       $$Güvenlik duvarı (firewall), ağ trafiğini önceden tanımlanmış kurallara göre süzer: İzin verilenler geçer, gerisi engellenir. En iyi yaklaşım varsayılan olarak her şeyi kapatıp yalnızca gerekenleri açmaktır (default deny).$$,
       $$HTTPS, HTTP trafiğini TLS ile şifreler; böylece aynı ağdaki biri gönderdiğin verileri okuyamaz ya da değiştiremez. Halka açık Wi-Fi ağlarında VPN, tüm trafiğini şifreli bir tünelden geçirerek ek bir koruma katmanı sağlar.$$],
 'qiQR5rTSshw', 'INTERMEDIATE', 40, 150, 250, 390, 2),
(12, 'owasp-top-10', 3, $$Web Güvenliği: OWASP Top 10$$,
 $$Web uygulamalarındaki en kritik açıkları; enjeksiyon, XSS ve erişim kontrolü hatalarını tanı ve önle.$$,
 ARRAY[$$OWASP Top 10 listesinin amacını açıklamak$$, $$SQL enjeksiyonunu parametreli sorgularla önlemek$$,
       $$XSS saldırılarını ve çıktı kodlamayı anlamak$$, $$Bozuk erişim kontrolünün (IDOR) riskini fark etmek$$],
 ARRAY[$$OWASP Top 10, web uygulamalarındaki en kritik güvenlik risklerini listeleyen, sektörün referans kabul ettiği bir rehberdir. Listenin başında bozuk erişim kontrolü yer alır: Kullanıcının yetkisi olmayan verilere ulaşabilmesi.$$,
       $$SQL enjeksiyonunda saldırgan, kullanıcı girdisi içine SQL kodu gizler. Çözüm basittir: Girdiyi asla sorguya metin olarak eklemeyip parametreli sorgular kullanmak. XSS'te ise saldırgan sayfaya zararlı JavaScript yerleştirir; çıktıyı her zaman kodlamak (encoding) bunu engeller.$$,
       $$IDOR, bir isteğin başka bir kullanıcının kimliğini taşıyarak onun adına işlem yapabilmesidir. Bu projenin ilk sürümünde de bu açık vardı: Quiz sonucu, istek gövdesindeki kullanıcı kimliğiyle kaydediliyordu. Yeni sürümde kimlik yalnızca doğrulanmış token'dan okunuyor.$$],
 'rWHvp7rUka8', 'INTERMEDIATE', 45, 150, 260, 540, 3),
(13, 'etik-hackerlik', 3, $$Etik Hackerlık ve Sızma Testi$$,
 $$Yetki dahilinde, planlı ve raporlu bir sızma testiyle sistemleri saldırganlardan önce test et.$$,
 ARRAY[$$Etik hackerlığın yasal ve etik sınırlarını bilmek$$, $$Sızma testinin aşamalarını sıralamak$$,
       $$Keşif ve tarama araçlarının rolünü anlamak$$, $$Bulguları önceliklendirip raporlamak$$],
 ARRAY[$$Etik hacker, sistemleri yazılı izin dahilinde ve tanımlı kapsamla test eden güvenlik uzmanıdır. İzinsiz yapılan her test, niyet ne olursa olsun yasa dışıdır; bu yüzden her sızma testi bir yetki belgesiyle başlar.$$,
       $$Tipik bir sızma testi beş aşamadan oluşur: Keşif (hedef hakkında bilgi toplama), tarama (açık port ve servisleri bulma; Nmap gibi araçlarla), erişim kazanma, erişimi sürdürme ve raporlama.$$,
       $$Testin asıl değeri rapordadır: Her bulgu risk seviyesine göre önceliklendirilir; nasıl tekrar üretileceği ve nasıl düzeltileceği açıkça yazılır. İyi bir etik hacker yalnızca açığı bulmaz, ekibin onu kapatmasına da yardım eder.$$],
 '2_lswM1S264', 'ADVANCED', 50, 200, 390, 460, 4);



